function SettingVoicePackBtn:StopUpdateCo()
    if isNotNull(self.coUpdateState) then
        CoStop(self.coUpdateState)
    end
end

function SettingVoicePackBtn:StartUpdateCo()
    if isNotNull(self.coUpdateState) then
        return
    end
    self.coUpdateState = CoStart(function()
        local doing = true
        while doing do
            local state, errorCode, errorMsg
            state, errorCode, errorMsg = self.operator:GetBatchSyncerState()
            if state == BatchSyncerState.Error then
                printError(errorMsg)
                doing = false
                self:SetUIError(errorMsg)
            else
                if state == BatchSyncerState.None then
                    local msg = localize("有点问题")
                    printError(msg)
                    doing = false
                    self:SetUIError(msg)
                elseif state == BatchSyncerState.UnChecked or
                state == BatchSyncerState.WaitDownload then
                    doing = false
                    self:SetUICanDownload()
                elseif state == BatchSyncerState.CheckingList then 
                    self:SetUICheckingList()
                elseif state == BatchSyncerState.Downloading then
                    self:SetUIDownloading()
                elseif state == BatchSyncerState.Finish then
                    doing = false
                    self:SetUIDownloaded()
                end
            end
            CoYield(1)
        end
        self.coUpdateState = nil
    end)
end

--- 可下载
function SettingVoicePackBtn:SetUICanDownload()
    CfUtils.FillText(self.Txt_Desc, localize("点击下载"))
    SetButtonAction(self.RT_ClickArea.gameObject, function()
        if isNotNull(self.operator) then
            CS.Engine.Tools.PlayerPrefsUtility.SetEncryptedString("AUDIO_DOWNLOAD", '1')
            self.operator:StartDownload()
            self:StartUpdateCo()
        end
    end)
    KTool.SetActive(self.RT_Select, false)
    KTool.SetActive(self.RT_RedPoint, true)
    KTool.SetActive(self.Txt_DownloadProgress, false)
    KTool.SetActive(self.Slider_DownloadProgress, false)
    CfUtils.SetUISwitchImage(self.SImg_BtnState.gameObject, BtnSwitchStatus.Black)
end

